<template>
  <div v-if="project.project_id">
    <div class="page-card"><div class="toolbar"><el-button @click="$router.back()">返回</el-button><strong>{{ project.project_name }}</strong><el-tag>{{ project.role }}</el-tag></div><el-descriptions :column="3" border><el-descriptions-item label="公司ID">{{ project.company_id }}</el-descriptions-item><el-descriptions-item label="项目编码">{{ project.project_code }}</el-descriptions-item><el-descriptions-item label="状态">{{ project.status }}</el-descriptions-item><el-descriptions-item label="Repository" :span="2">{{ project.repository||'-' }}</el-descriptions-item><el-descriptions-item label="默认分支">{{ project.default_branch }}</el-descriptions-item></el-descriptions></div>
    <el-tabs v-model="tab" class="page-card" style="margin-top:16px">
      <el-tab-pane label="项目成员" name="members"><div class="toolbar" v-if="owner"><el-select v-model="memberForm.user_id" filterable style="width:280px"><el-option v-for="x in userOptions" :key="x.user_id" :label="`${x.nick_name} (${x.user_name})`" :value="x.user_id"/></el-select><el-select v-model="memberForm.role" style="width:140px"><el-option label="OWNER" value="OWNER"/><el-option label="OPERATOR" value="OPERATOR"/><el-option label="VIEWER" value="VIEWER"/></el-select><el-button type="primary" @click="saveMember">保存成员</el-button></div><el-table :data="members"><el-table-column prop="user_name" label="账号"/><el-table-column prop="nick_name" label="昵称"/><el-table-column prop="role" label="角色"/><el-table-column v-if="owner" label="操作" width="100"><template #default="s"><el-button link type="danger" @click="deleteMember(s.row)">移除</el-button></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="资源目录与绑定" name="resources">
        <template v-if="owner"><div class="toolbar"><el-button @click="connectionVisible=true">新增连接</el-button><el-button @click="databaseVisible=true">新增数据库</el-button><el-button @click="objectVisible=true">新增表/Collection</el-button></div></template>
        <el-table :data="catalog" row-key="connection_id"><el-table-column prop="connection_name" label="连接" min-width="180"/><el-table-column prop="resource_type" label="类型" width="100"/><el-table-column prop="connection_code" label="编码" min-width="160"/><el-table-column label="数据库 / 对象" min-width="400"><template #default="s"><div v-for="db in s.row.databases" :key="db.database_id" style="margin-bottom:8px"><strong>{{ db.database_code }} → {{ db.database_name }}</strong><div class="muted" v-for="obj in db.objects" :key="obj.object_id">　{{ obj.object_type }}：{{ obj.object_code }} → {{ obj.object_name }}</div></div></template></el-table-column></el-table>
        <div class="page-title" style="margin-top:18px">逻辑资源绑定</div><div v-if="owner" class="toolbar"><el-input v-model="bindingForm.logical_name" placeholder="如 market.product_detail" style="width:260px"/><el-select v-model="bindingForm.target" style="width:480px"><el-option v-for="x in targetOptions" :key="x.value" :label="x.label" :value="x.value"/></el-select><el-button type="primary" @click="addBinding">添加</el-button><el-button type="success" @click="saveBindings">保存全部</el-button></div><el-table :data="bindings.resources"><el-table-column prop="logical_name" label="逻辑名称"/><el-table-column prop="resource_kind" label="类型"/><el-table-column label="目标"><template #default="s">{{ s.row.connection_id||s.row.database_id||s.row.object_id }}</template></el-table-column><el-table-column v-if="owner" label="操作" width="90"><template #default="s"><el-button link type="danger" @click="bindings.resources.splice(s.$index,1)">删除</el-button></template></el-table-column></el-table>
        <div class="page-title" style="margin-top:18px">逻辑密钥绑定</div><div v-if="owner" class="toolbar"><el-button @click="secretVisible=true">新增项目密钥</el-button><el-input v-model="secretForm.logical_name" placeholder="如 mysql.market.password" style="width:260px"/><el-select v-model="secretForm.secret_id" style="width:380px"><el-option v-for="x in secretOptions" :key="x.secret_id" :label="`${x.secret_code} / ${x.secret_name}`" :value="x.secret_id"/></el-select><el-button type="primary" @click="addSecret">添加</el-button><el-button type="success" @click="saveSecrets">保存全部</el-button></div><el-table :data="bindings.secrets"><el-table-column prop="logical_name" label="逻辑名称"/><el-table-column prop="secret_id" label="密钥ID"/><el-table-column v-if="owner" label="操作" width="90"><template #default="s"><el-button link type="danger" @click="bindings.secrets.splice(s.$index,1)">删除</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="发布通道" name="channels"><div v-if="owner" class="toolbar"><el-input v-model="channelForm.name" placeholder="stable" style="width:180px"/><el-select v-model="channelForm.release_id" style="width:500px"><el-option v-for="x in releases" :key="x.release_id" :label="`${x.version} / ${x.image_digest}`" :value="x.release_id"/></el-select><el-button type="primary" @click="saveChannel">设置通道</el-button></div><el-table :data="channels"><el-table-column prop="channel_name" label="通道"/><el-table-column prop="version" label="版本"/><el-table-column prop="image_digest" label="Digest" min-width="320"/></el-table></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="connectionVisible" title="新增资源连接" width="650px"><el-form label-width="110px"><el-form-item label="编码"><el-input v-model="connectionForm.connection_code"/></el-form-item><el-form-item label="名称"><el-input v-model="connectionForm.connection_name"/></el-form-item><el-form-item label="类型"><el-select v-model="connectionForm.resource_type"><el-option label="MySQL" value="MYSQL"/><el-option label="MongoDB" value="MONGO"/><el-option label="Redis" value="REDIS"/></el-select></el-form-item><el-form-item label="项目专属"><el-switch v-model="connectionForm.projectScoped"/></el-form-item><el-form-item label="配置 JSON"><el-input v-model="connectionForm.configText" type="textarea" :rows="10"/></el-form-item></el-form><template #footer><el-button @click="connectionVisible=false">取消</el-button><el-button type="primary" @click="createConnection">保存</el-button></template></el-dialog>
    <el-dialog v-model="databaseVisible" title="新增逻辑数据库" width="550px"><el-form label-width="110px"><el-form-item label="所属连接"><el-select v-model="databaseForm.connection_id" style="width:100%"><el-option v-for="x in catalog" :key="x.connection_id" :label="x.connection_name" :value="x.connection_id"/></el-select></el-form-item><el-form-item label="逻辑编码"><el-input v-model="databaseForm.database_code"/></el-form-item><el-form-item label="真实库名"><el-input v-model="databaseForm.database_name"/></el-form-item></el-form><template #footer><el-button @click="databaseVisible=false">取消</el-button><el-button type="primary" @click="createDatabase">保存</el-button></template></el-dialog>
    <el-dialog v-model="objectVisible" title="新增表或 Collection" width="550px"><el-form label-width="110px"><el-form-item label="所属数据库"><el-select v-model="objectForm.database_id" style="width:100%"><el-option v-for="x in databaseOptions" :key="x.database_id" :label="x.label" :value="x.database_id"/></el-select></el-form-item><el-form-item label="对象编码"><el-input v-model="objectForm.object_code"/></el-form-item><el-form-item label="真实名称"><el-input v-model="objectForm.object_name"/></el-form-item><el-form-item label="对象类型"><el-select v-model="objectForm.object_type"><el-option label="TABLE" value="TABLE"/><el-option label="COLLECTION" value="COLLECTION"/></el-select></el-form-item></el-form><template #footer><el-button @click="objectVisible=false">取消</el-button><el-button type="primary" @click="createObject">保存</el-button></template></el-dialog>
    <el-dialog v-model="secretVisible" title="新增项目密钥" width="560px"><el-form label-width="110px"><el-form-item label="密钥编码"><el-input v-model="newSecretForm.secret_code" placeholder="建议包含公司和项目编码"/></el-form-item><el-form-item label="显示名称"><el-input v-model="newSecretForm.secret_name"/></el-form-item><el-form-item label="密钥值"><el-input v-model="newSecretForm.value" type="password" show-password/></el-form-item><el-form-item label="说明"><el-input v-model="newSecretForm.description" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="secretVisible=false">取消</el-button><el-button type="primary" @click="createResourceSecret">保存</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import{computed,onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';import api from'../api';const route=useRoute(),id=Number(route.params.id),tab=ref('members'),project=reactive({}),members=ref([]),userOptions=ref([]),catalog=ref([]),secretOptions=ref([]),channels=ref([]),releases=ref([]),bindings=reactive({resources:[],secrets:[]}),memberForm=reactive({user_id:null,role:'VIEWER'}),bindingForm=reactive({logical_name:'',target:''}),secretForm=reactive({logical_name:'',secret_id:null}),channelForm=reactive({name:'stable',release_id:null}),connectionVisible=ref(false),databaseVisible=ref(false),objectVisible=ref(false),secretVisible=ref(false),newSecretForm=reactive({secret_code:'',secret_name:'',value:'',description:''}),connectionForm=reactive({connection_code:'',connection_name:'',resource_type:'MYSQL',projectScoped:true,configText:'{"host":"","port":3306,"username":"","password_secret":""}'}),databaseForm=reactive({connection_id:null,database_code:'',database_name:''}),objectForm=reactive({database_id:null,object_code:'',object_name:'',object_type:'TABLE'});const owner=computed(()=>project.role==='OWNER');const targetOptions=computed(()=>{const r=[];for(const c of catalog.value){r.push({label:`连接 ${c.connection_name}`,value:`CONNECTION:${c.connection_id}`});for(const d of c.databases){r.push({label:`数据库 ${c.connection_name}/${d.database_name}`,value:`DATABASE:${d.database_id}`});for(const o of d.objects)r.push({label:`${o.object_type} ${c.connection_name}/${d.database_name}/${o.object_name}`,value:`OBJECT:${o.object_id}`})}}return r});const databaseOptions=computed(()=>catalog.value.flatMap(c=>c.databases.map(d=>({database_id:d.database_id,label:`${c.connection_name}/${d.database_name}`}))));async function load(){Object.assign(project,(await api.get(`/projects/${id}`)).data);members.value=(await api.get(`/projects/${id}/members`)).data;userOptions.value=(await api.get(`/companies/${project.company_id}/user-options`)).data;catalog.value=(await api.get(`/resources/companies/${project.company_id}/catalog?project_id=${id}`)).data;Object.assign(bindings,(await api.get(`/resources/projects/${id}/bindings`)).data);channels.value=(await api.get(`/projects/${id}/channels`)).data;releases.value=(await api.get('/spider-releases')).data;if(owner.value)secretOptions.value=(await api.get(`/resources/projects/${id}/secret-options`)).data}async function saveMember(){try{await api.put(`/projects/${id}/members`,memberForm);ElMessage.success('已保存');load()}catch(e){ElMessage.error(e.response?.data?.detail||'保存失败')}}async function deleteMember(row){try{await api.delete(`/projects/${id}/members/${row.user_id}`);load()}catch(e){ElMessage.error(e.response?.data?.detail||'移除失败')}}function addBinding(){if(!bindingForm.logical_name||!bindingForm.target)return;const[k,v]=bindingForm.target.split(':');bindings.resources.push({logical_name:bindingForm.logical_name,resource_kind:k,connection_id:k==='CONNECTION'?Number(v):null,database_id:k==='DATABASE'?Number(v):null,object_id:k==='OBJECT'?Number(v):null});bindingForm.logical_name='';bindingForm.target=''}async function saveBindings(){await api.put(`/resources/projects/${id}/bindings`,bindings.resources);ElMessage.success('资源绑定已保存');load()}function addSecret(){if(secretForm.logical_name&&secretForm.secret_id)bindings.secrets.push({logical_name:secretForm.logical_name,secret_id:secretForm.secret_id})}async function saveSecrets(){await api.put(`/resources/projects/${id}/secret-bindings`,bindings.secrets);ElMessage.success('密钥绑定已保存');load()}async function saveChannel(){await api.put(`/projects/${id}/channels/${channelForm.name}`,{spider_release_id:channelForm.release_id});ElMessage.success('发布通道已更新');load()}async function createConnection(){try{await api.post('/resources/connections',{company_id:project.company_id,project_id:connectionForm.projectScoped?id:null,connection_code:connectionForm.connection_code,connection_name:connectionForm.connection_name,resource_type:connectionForm.resource_type,config:JSON.parse(connectionForm.configText),enabled:true});connectionVisible.value=false;load()}catch(e){ElMessage.error(e.response?.data?.detail||'创建失败')}}async function createDatabase(){try{await api.post('/resources/databases',{...databaseForm,config:{}});databaseVisible.value=false;load()}catch(e){ElMessage.error(e.response?.data?.detail||'创建失败')}}async function createObject(){try{await api.post('/resources/objects',objectForm);objectVisible.value=false;load()}catch(e){ElMessage.error(e.response?.data?.detail||'创建失败')}}async function createResourceSecret(){try{await api.post('/resources/secrets',{company_id:project.company_id,project_id:id,...newSecretForm,enabled:true});secretVisible.value=false;Object.assign(newSecretForm,{secret_code:'',secret_name:'',value:'',description:''});ElMessage.success('密钥已加密保存');load()}catch(e){ElMessage.error(e.response?.data?.detail||'创建失败')}}onMounted(load)
</script>
